export default function Contour({
  className = "",
  opacity = 0.5,
}: {
  className?: string;
  opacity?: number;
}) {
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      viewBox="0 0 800 400"
      preserveAspectRatio="xMidYMid slice"
      className={`pointer-events-none absolute inset-0 h-full w-full text-moss ${className}`}
      style={{ opacity }}
      fill="none"
      stroke="currentColor"
    >
      {CONTOURS.map((c, idx) => (
        <path
          key={idx}
          d={c.d}
          strokeWidth={c.i ? 1.1 : 0.6}
          strokeOpacity={c.i ? 0.85 : 0.5}
        />
      ))}
    </svg>
  );
}
